const repo = "acme/api";
const login = (x: any): string | null =>
  typeof x === "string" ? x : (x?.login ?? x?.username ?? x?.name ?? null);

const candidates: any[] = [];
for (let page = 1; page <= 50; page++) {
  const res: any = await tools.list_issues({ repo, state: "open", label: "security", page });
  const arr: any[] = Array.isArray(res) ? res : (res?.items ?? res?.issues ?? []);
  if (!arr.length) break;
  candidates.push(...arr);
  if (arr.length < 50) break;
}

const seen = new Set<number>();
const log: any[] = [];
for (const c of candidates) {
  const num = c.number;
  if (seen.has(num)) continue;
  seen.add(num);

  const full: any = await tools.get_issue({ repo, number: num });
  const state = full?.state ?? c.state;
  const labelNames: string[] = (full?.labels ?? c.labels ?? []).map((l: any) =>
    typeof l === "string" ? l : l?.name
  );
  const assignees: any[] = full?.assignees ?? (full?.assignee ? [full.assignee] : []);
  const author = login(full?.author ?? full?.user ?? full?.opened_by ?? full?.creator);

  const entry: any = { number: num, state, labels: labelNames, assignees: assignees.map(login), author };

  if (state !== "open" || !labelNames.includes("security")) {
    entry.action = "skipped (not open or no security label)";
  } else if (assignees.length > 0) {
    entry.action = "skipped (already assigned)";
  } else if (!author) {
    entry.action = "skipped (author unknown)";
  } else {
    try {
      await tools.assign({ repo, number: num, assignee: author });
      entry.action = `assigned to ${author}`;
    } catch (e: any) {
      entry.action = `error: ${e?.message ?? e}`;
    }
  }
  log.push(entry);
}

console.log(JSON.stringify({ candidateCount: candidates.length, log }, null, 2));
return log;
